$json = Get-Content "C:\Users\laksh\AppData\Local\Temp\claude\conv-extract\conversations.json" -Raw | ConvertFrom-Json
$conv = $json[0]

# Build a readable markdown transcript
$lines = @()
$lines += "# $($conv.name)"
$lines += ""
$lines += "Date: $($conv.created_at)"
$lines += "UUID: $($conv.uuid)"
$lines += ""
$lines += "---"
$lines += ""

foreach ($msg in $conv.chat_messages) {
    $role = if ($msg.sender -eq "human") { "**User**" } else { "**Claude**" }
    $lines += "## $role"
    $lines += ""
    # content can be an array of content blocks or a plain string
    if ($msg.content -is [System.Array]) {
        foreach ($block in $msg.content) {
            if ($block.type -eq "text") { $lines += $block.text }
        }
    } else {
        $lines += [string]$msg.content
    }
    $lines += ""
    $lines += "---"
    $lines += ""
}

$dest = "C:\Users\laksh\OneDrive - Nanyang Technological University\NTU\Y4S1\SC4053\Project\docs\ai-logs\exports\2026-10-23-claude-ai-research.md"
$lines | Out-File -FilePath $dest -Encoding utf8
